async function speechCacheKey(text:string,voice:string){
 const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(`french-paris-v1\n${voice}\n${text.trim()}`));
 const hash=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,"0")).join("");
 return new Request(`${window.location.origin}/api/speech/audio/${hash}`);
}

async function loadSpeech(text:string,audioFile?:string,voice="marin"){
 if(audioFile){const approved=await fetch(audioFile);if(approved.ok)return approved.blob()}
 const canCache="caches" in window;
 const cache=canCache?await caches.open(SPEECH_CACHE).catch(()=>null):null;
 const cacheKey=canCache?await speechCacheKey(text,voice):null;
 const cached=cacheKey?await cache?.match(cacheKey).catch(()=>undefined):null;
 if(cached)return cached.blob();
 const response=await fetch("/api/speech",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text,voice})});
 if(!response.ok)throw new Error();
 const blob=await response.blob();
 if(cache&&cacheKey)await cache.put(cacheKey,new globalThis.Response(blob,{headers:{"Content-Type":"audio/mpeg","Cache-Control":"max-age=2592000"}})).catch(()=>undefined);
 return blob;
}

function getYouTubeId(value:string){
 try{
  const url=new URL(value.trim());
  if(url.hostname==="youtu.be")return url.pathname.slice(1).split("/")[0];
  if(url.hostname.endsWith("youtube.com")){
   if(url.pathname==="/watch")return url.searchParams.get("v");
   const match=url.pathname.match(/^\/(?:shorts|embed|live)\/([^/?]+)/);
   return match?.[1]||null;
  }
 }catch{return null}
 return null;
}

function formatTime(seconds:number){const safe=Number.isFinite(seconds)?Math.max(0,Math.round(seconds)):0;return `${Math.floor(safe/60)}:${String(safe%60).padStart(2,"0")}`}

function ClipTimeline({duration,start,end,onStart,onEnd}:{duration:number;start:number;end:number;onStart:(value:number)=>void;onEnd:(value:number)=>void}){
 const railRef=useRef<HTMLDivElement|null>(null),dragRef=useRef<{x:number;start:number;end:number}|null>(null);
 const knownDuration=Number.isFinite(duration)&&duration>0;const maximum=Math.max(10,Math.round(duration||end||60)),minimumGap=Math.min(5,maximum),left=Math.min(100,start/maximum*100),width=Math.max(0,(end-start)/maximum*100);
 const updateStart=(value:number)=>onStart(Math.max(0,Math.min(value,end-minimumGap)));
 const updateEnd=(value:number)=>onEnd(Math.min(maximum,Math.max(value,start+minimumGap)));
 const moveBlock=(nextStart:number)=>{const length=end-start,clamped=Math.max(0,Math.min(maximum-length,nextStart));onStart(clamped);onEnd(clamped+length)};
 const moveDrag=(clientX:number)=>{const drag=dragRef.current,rail=railRef.current;if(!drag||!rail)return;const delta=Math.round((clientX-drag.x)/rail.getBoundingClientRect().width*maximum),length=drag.end-drag.start,nextStart=Math.max(0,Math.min(maximum-length,drag.start+delta));onStart(nextStart);onEnd(nextStart+length)};
 return <section className="clip-editor" aria-label="Choose the video passage"><header><div><span className="eyebrow">Selected passage</span><strong>{formatTime(start)} <i>to</i> {formatTime(end)}</strong></div><em>{formatTime(end-start)} of {knownDuration?formatTime(maximum):"unknown video length"}</em></header><div className="range-stage" ref={railRef}><div className="range-rail"/><div className="range-selection" role="slider" tabIndex={0} aria-label="Move selected passage" aria-valuemin={0} aria-valuemax={maximum} aria-valuenow={start} aria-valuetext={`${formatTime(start)} to ${formatTime(end)}`} style={{left:`${left}%`,width:`${width}%`}} onPointerDown={event=>{dragRef.current={x:event.clientX,start,end};event.currentTarget.setPointerCapture(event.pointerId)}} onPointerMove={event=>moveDrag(event.clientX)} onPointerUp={event=>{moveDrag(event.clientX);dragRef.current=null;event.currentTarget.releasePointerCapture(event.pointerId)}} onPointerCancel={()=>{dragRef.current=null}} onKeyDown={event=>{if(event.key!=="ArrowLeft"&&event.key!=="ArrowRight")return;event.preventDefault();moveBlock(start+(event.key==="ArrowRight"?(event.shiftKey?5:1):event.shiftKey?-5:-1))}}><span>Drag to move</span></div><input className="range-input range-start" type="range" min={0} max={maximum} step={1} value={start} onChange={event=>updateStart(Number(event.target.value))} aria-label="Clip start time"/><input className="range-input range-end" type="range" min={0} max={maximum} step={1} value={end} onChange={event=>updateEnd(Number(event.target.value))} aria-label="Clip end time"/></div><div className="range-times"><span>Start · 0:00</span><span>{knownDuration?`Full video · ${formatTime(maximum)}`:"Video length loading · try starting playback"}</span></div><div className="clip-editor-footer"><div className="clip-time-fields"><label>Start <input type="number" min={0} max={Math.max(0,end-minimumGap)} value={start} onChange={event=>updateStart(Number(event.target.value))}/><span>sec</span></label><label>End <input type="number" min={start+minimumGap} max={maximum} value={end} onChange={event=>updateEnd(Number(event.target.value))}/><span>sec</span></label></div><div className="clip-presets" aria-label="Clip length">{[30,60,90].map(length=><button key={length} disabled={length>maximum} onClick={()=>onEnd(Math.min(maximum,start+length))}>{length}s</button>)}</div></div><p>Drag the pink passage to move it. Drag either white handle to change its length.</p></section>
}

