function SelectionSaver({saved,onSave}:{saved:string[];onSave:(text:string,context:PhraseContext)=>void}){
 const [capture,setCapture]=useState<{text:string;context:PhraseContext;left:number;top:number}|null>(null),[notice,setNotice]=useState("");
 useEffect(()=>{const inspect=()=>{window.setTimeout(()=>{const selection=window.getSelection();const text=selection?.toString().replace(/\s+/g," ").trim()||"";if(!selection||selection.isCollapsed||text.length<2||text.length>220){setCapture(null);return}const range=selection.getRangeAt(0);const node=range.commonAncestorContainer;const element=(node.nodeType===Node.ELEMENT_NODE?node:node.parentElement) as Element|null;const frenchSurface=".decode-card>p,.full-transcript p,.phrase-note strong,.library-grid h2,.library-grid article>p,.daily-note h2,.passage strong,.session-rail h2,.studio-transcript>p";const surface=element?.closest(frenchSurface);if(!surface){setCapture(null);return}const source=surface.closest<HTMLElement>("[data-phrase-source]")?.dataset.phraseSource||"";const library=source.startsWith("library:")?passages.find(p=>p.id===source.slice(8)):null;const surfaceText=(surface.textContent||text).replace(/^\d{2}\s*/u,"").replace(/^[▶Ⅱ]\s*/u,"").trim();const sentence=sentenceForPhrase(library?.text.toLocaleLowerCase().includes(text.toLocaleLowerCase())?library.text:surfaceText,text);const rect=range.getBoundingClientRect();setCapture({text,context:{sentence,source},left:Math.min(window.innerWidth-150,Math.max(12,rect.left+rect.width/2-62)),top:Math.max(12,rect.top-48)})},0)};document.addEventListener("mouseup",inspect);document.addEventListener("touchend",inspect);return()=>{document.removeEventListener("mouseup",inspect);document.removeEventListener("touchend",inspect)}},[]);
 const save=()=>{if(!capture)return;onSave(capture.text,capture.context);setNotice(saved.includes(capture.text)?"Saved phrase context updated":"Saved for review");window.getSelection()?.removeAllRanges();setCapture(null);window.setTimeout(()=>setNotice(""),2200)};
 return <>{capture&&<button className="selection-save" style={{left:capture.left,top:capture.top}} onMouseDown={event=>event.preventDefault()} onClick={save}><span>＋</span> Save phrase</button>}{notice&&<div className="save-notice" role="status">{notice}</div>}</>
}

