 useEffect(()=>{if(!navigationReady.current){navigationReady.current=true;return}const hash="#"+view+(view==="practice"?"/"+passageId:view==="studio"&&videoId?"/"+videoId:"");if(window.location.hash!==hash)window.history.pushState(null,"",hash)},[view,passageId,videoId]);
 useEffect(()=>{const apply=(data:any)=>{if(typeof data?.xp==="number")legacyXp.current=data.xp;if(Array.isArray(data?.completed))setCompleted(data.completed);if(Array.isArray(data?.savedPhrases))setSavedPhrases(data.savedPhrases);setPhraseContexts(validPhraseContexts(data?.phraseContexts));if(data?.phraseReviews&&typeof data.phraseReviews==="object")setPhraseReviews(data.phraseReviews);if(Array.isArray(data?.speakingAttempts))setSpeakingAttempts(data.speakingAttempts.slice(0,30));if(Array.isArray(data?.feedbackNotes))setFeedbackNotes(data.feedbackNotes.slice(0,100));if(holidayThemes.some(theme=>theme.id===data?.holidayTheme))setHolidayTheme(data.holidayTheme);if(typeof data?.lastSeenUpdateId==="string")setLastSeenUpdateId(data.lastSeenUpdateId);if(Array.isArray(data?.practiceDates))setPracticeDates(data.practiceDates);if(data?.reviews&&typeof data.reviews==="object")setReviews(data.reviews);if(data?.reviewRatings&&typeof data.reviewRatings==="object")setReviewRatings(data.reviewRatings);if(data?.listeningPatterns&&typeof data.listeningPatterns==="object")setListeningPatterns(data.listeningPatterns)};fetch("/api/progress",{cache:"no-store"}).then(response=>response.ok?response.json():null).then(data=>{if(!data||data.syncUnavailable)throw Error("Progress sync is unavailable. Reload before practicing so your saved work is not overwritten.");progressCacheKey.current=`${PROGRESS_KEY}:${data.userId}`;if(data.state)apply(data.state);setSyncState("synced");setProgressLoaded(true)}).catch(error=>setProgressLoadError(error.message))},[]);
 useEffect(()=>{if(!progressLoaded)return;const state={xp:legacyXp.current,completed,savedPhrases,phraseContexts,phraseReviews,speakingAttempts,feedbackNotes,holidayTheme,lastSeenUpdateId,practiceDates,reviews,reviewRatings,listeningPatterns};try{localStorage.setItem(progressCacheKey.current,JSON.stringify(state))}catch{}setSyncState("syncing");const timer=window.setTimeout(()=>fetch("/api/progress",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(state)}).then(response=>{if(response.status===200)setSyncState("synced");else setSyncState("local")}).catch(()=>setSyncState("local")),700);return()=>window.clearTimeout(timer)},[xp,completed,savedPhrases,phraseContexts,phraseReviews,speakingAttempts,feedbackNotes,holidayTheme,lastSeenUpdateId,practiceDates,reviews,reviewRatings,listeningPatterns,progressLoaded]);
 useEffect(()=>()=>{audioRef.current?.pause();if(audioUrlRef.current)URL.revokeObjectURL(audioUrlRef.current)},[]);
