 const toggleSample=async()=>{if(captureActive())return;if(!playing)playCount.current++;if(audioRef.current){if(playing){audioRef.current.pause();setPlaying(false)}else{if(audioRef.current.ended)audioRef.current.currentTime=0;await audioRef.current.play();setPlaying(true)}return}setVoiceError("");setPlaying(true);try{const url=URL.createObjectURL(await loadSpeech(passage.text,passage.audioFile,passage.speaker.voice));audioUrlRef.current=url;const audio=new Audio(url);audioRef.current=audio;audio.onplay=()=>{if(captureActive()){audio.pause();setPlaying(false)}};audio.onloadedmetadata=()=>{setDuration(audio.duration);audio.currentTime=Math.min(audioPosition,Math.max(0,audio.duration-.1))};audio.ontimeupdate=()=>{setProgress(audio.duration?audio.currentTime/audio.duration*100:0);setAudioPosition(Math.floor(audio.currentTime))};audio.onended=()=>{setPlaying(false);setProgress(100)};audio.onerror=()=>{setPlaying(false);setVoiceError("The natural voice is temporarily unavailable.")};await audio.play()}catch{clearAudio();setVoiceError("The natural voice is temporarily unavailable.")}};
