 const scheduleReview=(id:string,rating:"Again"|"Hard"|"Good"|"Easy")=>{const days={Again:0,Hard:1,Good:3,Easy:7}[rating];setReviews(items=>({...items,[id]:new Date(Date.now()+days*86400000).toISOString()}));setReviewRatings(items=>({...items,[id]:rating}))};
