 const advance=async()=>{audioRef.current?.pause();setPlaying(false);if(step<3){if(step===0)setFirstSummary(text);setStep(step+1)}else{const today=new Date().toISOString().slice(0,10);const firstCompletion=!completed.includes(passage.id);const result=await record({kind:firstCompletion?"loop":"review",source:"library:"+passage.id,usageSessionId:usage.sessionId(),summary:firstSummary,retell,decoded:diagnosis.length>0,rehearsed:shadowDone});if(!result)return;setSessionXp(result.awarded||0);setDone(true);setCompleted(items=>items.includes(passage.id)?items:[...items,passage.id]);setPracticeDates(items=>items.includes(today)?items:[...items,today]);scheduleReview(passage.id,"Good");if(diagnosis.length)setListeningPatterns(items=>{const next={...items};diagnosis.filter(item=>item!=="I understood it").forEach(item=>next[item]=(next[item]||0)+1);return next})}};
 const assessUnderstanding=async()=>{setAssessing(true);setAssessmentError("");try{const response=await fetch("/api/comprehension",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({summary:text,passage:passage.text,level:passage.level})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Feedback is unavailable.");setAssessment(data);setFirstSummary(text);await record({kind:"observation",source:"library:"+passage.id,score:data.score,condition:completed.includes(passage.id)?"familiar":playCount.current>1?"replay":"first"})}catch(error){setAssessmentError(error instanceof Error?error.message:"Feedback is unavailable.")}finally{setAssessing(false)}};
