 {step>0&&step!==2&&<Player passage={passage} playing={playing} onToggle={toggleSample} onReplay={replaySample} progress={progress} duration={duration}/>}
 {step===1&&<div className="decode-card"><p><button className="line-play" onClick={toggleSample} aria-label={playing?"Pause passage":"Play passage"}>{playing?"Ⅱ":"▶"}</button> « {passage.decode} »</p><div className="translation">{passage.translation}</div><details className="full-transcript" open={transcriptOpen} onToggle={event=>setTranscriptOpen(event.currentTarget.open)}><summary>Reveal full transcript</summary>{passage.text.split(/(?<=[.!?])\s+/).map((sentence,index)=><p key={sentence}><span>{String(index+1).padStart(2,"0")}</span>{sentence}</p>)}</details><div className="diagnosis"><span>What made this difficult?</span>{["New expression","Speech too fast","Sounded different","I understood it"].map(x=><button key={x} aria-pressed={diagnosis.includes(x)} className={diagnosis.includes(x)?"selected":""} onClick={()=>setDiagnosis(items=>items.includes(x)?items.filter(item=>item!==x):[...items,x])}>{x}</button>)}</div><div className="phrase-note"><strong>{passage.phrase}</strong><span>{passage.meaning}</span><button aria-pressed={savedPhrases.includes(passage.phrase)} className={savedPhrases.includes(passage.phrase)?"saved":""} onClick={toggleSavedPhrase}>{savedPhrases.includes(passage.phrase)?"✓ Saved":"＋ Save phrase"}</button></div></div>}
 {step===2&&<Rehearse key={passage.id+passage.text} source={"library:"+passage.id} text={passage.text} completed={shadowDone} onComplete={()=>setShadowDone(true)} loadAudio={text=>loadSpeech(text,undefined,passage.speaker.voice)} recorder={phrase=><VoiceRecorder label="Record rehearsal" recording={recording} setRecording={setRecording} onAttempt={rememberSpeaking} referenceText={phrase}/>} onRetry={()=>record({kind:"rehearse",source:"library:"+passage.id,repeated:true})}/>}
