export default function Page(){return <AccessGate><Home/></AccessGate>}

function HomeView({xp,completed,savedPhrases,phraseContexts,phraseReviews,speakingAttempts,practiceDates,reviews,listeningPatterns,syncState,reviewNotice,onClearNotice,onRatePhrase,onExport,onPractice,onNavigate}:{xp:number;completed:string[];savedPhrases:string[];phraseContexts:Record<string,PhraseContext>;phraseReviews:Record<string,string>;speakingAttempts:SpeakingAttempt[];practiceDates:string[];reviews:Record<string,string>;listeningPatterns:Record<string,number>;syncState:"local"|"syncing"|"synced";reviewNotice:string;onClearNotice:()=>void;onRatePhrase:(phrase:string,rating:"Again"|"Hard"|"Good"|"Easy")=>Promise<boolean>;onExport:()=>void;onPractice:(id:string,fromReview?:boolean)=>void;onNavigate:(view:"today"|"practice"|"library"|"studio"|"progress")=>void}){
 const now=new Date();
 const savedCount=savedPhrases.length;
 const duePhrases=savedPhrases.filter(phrase=>!phraseReviews[phrase]||new Date(phraseReviews[phrase])<=now);
 const due=passages.filter(p=>reviews[p.id]&&new Date(reviews[p.id])<=now);
 const patterns=Object.entries(listeningPatterns).sort((a,b)=>b[1]-a[1]);
 const topPattern=patterns[0]?.[0];
 const nextLesson=topPattern==="Speech too fast"?passages.find(p=>p.id==="train"):topPattern==="Sounded different"?passages.find(p=>p.id==="pluie"):passages.find(p=>!completed.includes(p.id))||passages[0];
 const primary=due[0]||nextLesson;
 const week=Array.from({length:7},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(6-index));const key=date.toISOString().slice(0,10);return {key,label:date.toLocaleDateString("en-US",{weekday:"short"}).slice(0,1),active:practiceDates.includes(key),today:index===6}});
 const nextReview=Object.values(reviews).filter(date=>new Date(date)>now).sort()[0];
 return <section className="home-view" aria-labelledby="home-title">
  {reviewNotice&&<div className="review-confirmation" role="status"><span>✓</span><strong>{reviewNotice}</strong><button onClick={onClearNotice} aria-label="Dismiss review confirmation">×</button></div>}
  <div className="home-intro">
   <div><p className="eyebrow">Today’s listening brief</p><h1 id="home-title">Bonjour, Nikki.</h1><p>Small, attentive sessions are turning real French into something your ear can hold.</p></div>
   <div className="sync-tools"><span className={`sync-state ${syncState}`}>{syncState==="synced"?"✓ Progress synced":syncState==="syncing"?"Syncing…":"Saved on this device"}</span><button onClick={onExport}>Export backup</button></div>
  </div>
  <div className="home-grid">
   <article className="daily-note" data-phrase-source={`library:${primary.id}`}><div className="note-top"><span>{due.length?"Review is ready":"Today’s recommendation"}</span><small>{primary.level} · {primary.topic}</small></div><div className="note-copy"><p>{due.length?"Before you learn anything new":"A good next stretch"}</p><h2>{primary.title}</h2><p>{due.length?"Listen once without reading. Notice what now feels obvious, then rate how easily it came back.":topPattern?`Chosen to work on “${topPattern.toLowerCase()},” the listening obstacle you’ve marked most often.`:"Start with one everyday story and let the four-step routine do the work."}</p></div><button onClick={()=>onPractice(primary.id,due.length>0)}>{due.length?"Review this passage":"Start today’s lesson"} <span>→</span></button><div className="note-stamp">à<br/>l’oreille</div></article>
   <div className="home-side"><article className="week-card"><div><p className="eyebrow">Your week</p><strong>{practiceDates.length} listening {practiceDates.length===1?"day":"days"} so far</strong></div><div className="week-dots">{week.map(day=><div key={day.key} className={day.active?"active":day.today?"today":""}><i>{day.active?"✓":""}</i><span>{day.label}</span></div>)}</div><p>Consistency matters more than keeping a perfect streak.</p></article><article className="home-stats"><div><strong>{completed.length}<span>/{passages.length}</span></strong><small>lessons complete</small></div><div><strong>{savedCount}</strong><small>phrases kept</small></div><div><strong>{xp}</strong><small>total XP</small></div></article></div>
  </div>
  <PhraseReviewDeck phrases={duePhrases} contexts={phraseContexts} onRate={onRatePhrase}/>
  <div className="home-lower">
   <article className="insight-card"><div><p className="eyebrow">Listening insight</p><h2>{topPattern||"Your earprint starts here"}</h2><p>{topPattern?"This keeps appearing in your Decode notes. The app will favor passages that help you hear it more clearly.":"Mark what made a passage difficult during Decode, and this space will reveal useful patterns over time."}</p></div><div className="mini-patterns">{patterns.length?patterns.slice(0,3).map(([label,count])=><div key={label}><span>{label}</span><i><b style={{width:`${Math.max(20,count/(patterns[0][1]||1)*100)}%`}}/></i></div>):<span className="no-pattern">Complete a lesson to unlock your first insight.</span>}</div><button onClick={()=>onNavigate("library")}>Find a matching lesson →</button></article>
   <DailyReviewCard dueLessons={due} duePhrases={duePhrases} nextReview={nextReview} onReviewLesson={id=>onPractice(id,true)} onReviewPhrases={()=>document.getElementById("phrase-review")?.scrollIntoView({behavior:"smooth",block:"center"})}/>
   <article className="studio-card"><span className="studio-orbit">écoute</span><div><p className="eyebrow">Listening studio</p><h2>Bring something she already loves.</h2><p>Turn a recipe, interview, or travel video into a focused one-minute French drill.</p><button onClick={()=>onNavigate("studio")}>Open Studio →</button></div></article>
  </div>
  <SpeakingHistory attempts={speakingAttempts}/>
 </section>
}

function DailyReviewCard({dueLessons,duePhrases,nextReview,onReviewLesson,onReviewPhrases}:{dueLessons:Passage[];duePhrases:string[];nextReview?:string;onReviewLesson:(id:string)=>void;onReviewPhrases:()=>void}){
 const total=dueLessons.length+duePhrases.length;
 const firstLesson=dueLessons[0];
 return <article className={`queue-card interactive ${total?"has-items":"complete"}`}><div className="queue-heading"><div><p className="eyebrow">Daily review</p><h2>{total?"Your review path":"All caught up"}</h2></div><strong>{total?total:"✓"}<small>{total?total===1?"item":"items":"done"}</small></strong></div>{total?<><p>Complete each step and it will be scheduled for its next appearance.</p><ol className="review-path"><li className={duePhrases.length?"ready":"done"}><span>{duePhrases.length?"1":"✓"}</span><div><strong>Saved phrases</strong><small>{duePhrases.length?`${duePhrases.length} ready for recall`:"Complete"}</small></div>{duePhrases.length>0&&<button onClick={onReviewPhrases}>Review phrases →</button>}</li><li className={firstLesson?"ready":"done"}><span>{firstLesson?duePhrases.length?"2":"1":"✓"}</span><div><strong>Listening passage</strong><small>{firstLesson?firstLesson.title:"Complete"}</small></div>{firstLesson&&<button onClick={()=>onReviewLesson(firstLesson.id)}>Open passage →</button>}</li></ol></>:<><p>Your review is complete. New items will appear here when they are ready.</p><div className="queue-complete-mark">✓ Review complete</div>{nextReview&&<small className="next-review-date">Next review · {new Date(nextReview).toLocaleDateString("en-US",{month:"short",day:"numeric"})}</small>}</>}</article>
}

function phraseDetails(phrase:string,context?:PhraseContext){
 const libraryId=context?.source.startsWith("library:")?context.source.slice(8):"";
 const source=passages.find(p=>p.id===libraryId)||passages.find(p=>p.phrase===phrase||p.text.includes(phrase));
 const studio=context?.source.match(/^studio:([A-Za-z0-9_-]{11}):(\d+):(\d+)$/);
 const sentence=context?.sentence|| (source?sentenceForPhrase(source.text,phrase):"");
 const title=studio?`Studio video · ${formatTime(Number(studio[2]))}–${formatTime(Number(studio[3]))}`:source?.title||"Saved French";
 const href=studio?`https://www.youtube.com/watch?v=${studio[1]}&t=${studio[2]}s`:source?`#practice/${source.id}`:null;
 return {sentence,title,href,voice:source?.speaker.voice};
}

function PhraseReviewDeck({phrases,contexts,onRate}:{phrases:string[];contexts:Record<string,PhraseContext>;onRate:(phrase:string,rating:"Again"|"Hard"|"Good"|"Easy")=>Promise<boolean>}){
 const [index,setIndex]=useState(0),[revealed,setRevealed]=useState(false),[ratingPending,setRatingPending]=useState(false),[audioError,setAudioError]=useState(""),[audioBusy,setAudioBusy]=useState(false);const ratingBusy=useRef(false),audioRef=useRef<HTMLAudioElement|null>(null),audioUrlRef=useRef(""),playGeneration=useRef(0);
 const phrase=phrases[index%Math.max(phrases.length,1)];
 const details=phrase?phraseDetails(phrase,contexts[phrase]):null;
 const stopAudio=()=>{playGeneration.current++;audioRef.current?.pause();audioRef.current=null;if(audioUrlRef.current)URL.revokeObjectURL(audioUrlRef.current);audioUrlRef.current=""};
 useEffect(()=>()=>stopAudio(),[]);
 const rate=async(rating:"Again"|"Hard"|"Good"|"Easy")=>{if(ratingBusy.current||!phrase)return;ratingBusy.current=true;setRatingPending(true);try{if(await onRate(phrase,rating)){stopAudio();setAudioBusy(false);setRevealed(false);setIndex(0)}}finally{ratingBusy.current=false;setRatingPending(false)}};
 const play=async(text:string)=>{if(captureActive())return;stopAudio();const generation=playGeneration.current;setAudioBusy(true);setAudioError("");try{const blob=await loadSpeech(text,undefined,details?.voice);if(generation!==playGeneration.current)return;const url=URL.createObjectURL(blob);audioUrlRef.current=url;const audio=new Audio(url);audioRef.current=audio;audio.onended=()=>{if(generation===playGeneration.current){stopAudio();setAudioBusy(false)}};audio.onerror=()=>{if(generation===playGeneration.current){stopAudio();setAudioBusy(false);setAudioError("Audio could not play. Please try again.")}};await audio.play()}catch{if(generation===playGeneration.current){stopAudio();setAudioBusy(false);setAudioError("Audio is unavailable right now.")}}};
 if(!phrase||!details)return <section className="phrase-review empty" id="phrase-review"><div><p className="eyebrow">Phrase review</p><h2>Your phrase queue is clear.</h2><p>Highlight French in a lesson or the Library to build a personal review deck.</p></div></section>;
 return <section className="phrase-review" id="phrase-review"><div className="phrase-review-head"><div><p className="eyebrow">Phrase review · {phrases.length} due</p><h2>Recall it before you reveal it.</h2></div>{audioBusy?<button onClick={()=>{stopAudio();setAudioBusy(false)}} aria-label="Stop phrase audio">■ Stop audio</button>:<button onClick={()=>void play(phrase)} aria-label="Play saved phrase">▶ Hear phrase</button>}</div><blockquote lang="fr">{phrase}</blockquote>{revealed?<><div className="phrase-context"><span>{details.title}</span>{details.sentence&&details.sentence!==phrase&&<p lang="fr">{details.sentence}</p>}{details.href&&<a href={details.href} target={details.href.startsWith("https:")?"_blank":undefined} rel={details.href.startsWith("https:")?"noopener noreferrer":undefined}>Open source →</a>}{details.sentence&&details.sentence!==phrase&&<button disabled={audioBusy} onClick={()=>void play(details.sentence)}>▶ Hear sentence</button>}</div><fieldset disabled={ratingPending}><legend className="eyebrow">{ratingPending?"Saving review…":"How did recall feel?"}</legend><ReviewRating onRate={rate}/></fieldset></>:<button className="reveal-phrase" onClick={()=>setRevealed(true)}>Reveal context</button>}{audioError&&<p role="alert">{audioError}</p>}</section>
}

function SpeakingHistory({attempts}:{attempts:SpeakingAttempt[]}){
 return <section className="speaking-history"><div><p className="eyebrow">Speaking history</p><h2>{attempts.length?"Your voice, getting freer.":"Your speaking attempts will collect here."}</h2><p>{attempts.length?"Compare the transcript and next drill from recent rehearsal and retelling attempts.":"Record during Rehearse or Retell to keep the transcript, coaching, and next drill."}</p></div>{attempts.length>0&&<div className="attempt-list">{attempts.slice(0,5).map(attempt=><article key={attempt.id}><div><span>{new Date(attempt.createdAt).toLocaleDateString("en-US",{month:"short",day:"numeric"})}</span><strong>{attempt.task}</strong><em>{attempt.level} · {attempt.score}/100</em></div><blockquote>{attempt.transcript}</blockquote><p>{attempt.summary}</p><small>Next drill · {attempt.nextDrill}</small></article>)}</div>}</section>
}

function LibraryView({completed,savedPhrases,phraseContexts,reviews,onChoose,onRemovePhrase}:{completed:string[];savedPhrases:string[];phraseContexts:Record<string,PhraseContext>;reviews:Record<string,string>;onChoose:(id:string)=>void;onRemovePhrase:(phrase:string)=>void}){
 return <section className="standalone-view" aria-labelledby="library-title">
  <p className="eyebrow">Lesson library</p><h1 id="library-title">Choose what your ear needs next.</h1><p className="intro">Move from everyday B1 conversation toward the nuance and pace of B2 French. Highlight any French in a passage to save exactly what matters.</p>
  <div className="library-grid">{passages.map(p=>{const due=reviews[p.id]&&new Date(reviews[p.id])<=new Date();return <article key={p.id} data-phrase-source={`library:${p.id}`} className={completed.includes(p.id)?"complete":""}><div><span>{p.level}</span><em>{p.topic}</em></div><h2>{p.title}</h2><p>{p.text}</p><footer><small>{due?"Review due now":completed.includes(p.id)?"Completed":"New lesson"}</small><button onClick={()=>onChoose(p.id)}>{due?"Review lesson":completed.includes(p.id)?"Practice again":"Start lesson"} →</button></footer></article>})}</div>
  <div className="phrase-library"><div><p className="eyebrow">Phrase notebook</p><h2>{savedPhrases.length?savedPhrases.length+" phrases worth keeping":"Your saved phrases will live here."}</h2></div>{savedPhrases.length?<div>{savedPhrases.map(phrase=>{const details=phraseDetails(phrase,phraseContexts[phrase]);return <article key={phrase}><div><strong lang="fr">{phrase}</strong><span>{details.title}</span>{details.sentence&&details.sentence!==phrase&&<p lang="fr">{details.sentence}</p>}{details.href&&<a href={details.href} target={details.href.startsWith("https:")?"_blank":undefined} rel={details.href.startsWith("https:")?"noopener noreferrer":undefined}>Open source →</a>}</div><button onClick={()=>onRemovePhrase(phrase)} aria-label={`Remove ${phrase}`}>×</button></article>})}</div>:<p>Highlight any French phrase or sentence, then choose “Save phrase.” It will appear here for review.</p>}</div>
 </section>
}

function ReviewRating({value,onRate}:{value?:string;onRate:(rating:"Again"|"Hard"|"Good"|"Easy")=>void}){
 const choices=[["Again","Today"],["Hard","Tomorrow"],["Good","3 days"],["Easy","1 week"]] as const;
 return <div className="review-rating" aria-label="Choose the next review interval"><span>When should this return?</span><div>{choices.map(([rating,interval])=><button key={rating} className={value===rating?"selected":""} aria-pressed={value===rating} onClick={()=>onRate(rating)}><strong>{rating}</strong><small>{interval}</small></button>)}</div></div>
}

function AboutView({completed,saved,speaking,patterns}:{completed:number;saved:number;speaking:number;patterns:Record<string,number>}){
 const stage=completed===0?0:completed<4?1:completed<9?2:3;
 const topPattern=Object.entries(patterns).sort((a,b)=>b[1]-a[1])[0]?.[0];
 const guidance=[
  {label:"Your first week",title:"Begin by trusting your ear.",copy:"Nikki, this app was made for where you are now: you know more French than fast conversation lets you access. Start with short B1 stories. On the first listen, understanding the situation is enough."},
  {label:"Building recognition",title:"You are teaching sound to become meaning.",copy:"The goal is not to memorize every transcript. It is to notice phrases at natural speed, understand why they slipped past, and meet them again before they fade."},
  {label:"Growing independence",title:"Your listening is becoming active.",copy:"You are ready to mix structured passages with Studio clips. Keep captions hidden at first, then use the transcript as evidence—not as a substitute for listening."},
  {label:"Toward B2",title:"Now variety matters.",copy:"Your ear benefits from different speakers, topics, speeds, and opinions. Retelling and rehearsal will help turn comprehension into French you can use spontaneously."},
 ][stage];
 return <section className="about-view" aria-labelledby="about-title"><div className="about-letter"><p className="eyebrow">Why À l’Oreille exists</p><h1 id="about-title">French that reaches you before the subtitles do.</h1><p className="about-lede">This is not a vocabulary game or a race for a streak. It is a listening coach created for you, Nikki, while you grow from understanding written French into following the living, everyday language people actually speak.</p><div className="letter-signoff"><span>Made with care for your French journey</span><strong>à l’oreille</strong></div></div><div className="about-now"><div><span>{String(stage+1).padStart(2,"0")}</span><p className="eyebrow">{guidance.label}</p><h2>{guidance.title}</h2><p>{guidance.copy}</p>{topPattern&&<p className="personal-note"><b>Your current listening focus:</b> {topPattern.toLowerCase()}.</p>}</div><div className="about-tally"><div><strong>{completed}</strong><span>lessons heard</span></div><div><strong>{saved}</strong><span>phrases kept</span></div><div><strong>{speaking}</strong><span>times you spoke</span></div></div></div><div className="loop-explainer"><p className="eyebrow">The learning loop</p><h2>Every source becomes four useful encounters.</h2><div>{labels.map((item,index)=><article key={item.name}><span>0{index+1}</span><h3>{item.name}</h3><p>{["Listen without reading and catch the situation before the details.","Reveal the words, diagnose the gap, and save language worth keeping.","Practise a short phrase by listening then echoing, rebuilding it, or noticing its rhythm. Speaking is optional.","Explain the idea in your own French so recognition becomes expression."][index]}</p></article>)}</div></div><div className="about-principles"><article><h2>You do not need every word.</h2><p>Real listening is prediction, context, repair, and confidence. Missing a word is information—not failure.</p></article><article><h2>Your data serves the next lesson.</h2><p>Saved phrases, difficult sounds, reviews, and speaking attempts quietly shape what the app recommends next.</p></article><article><h2>The app will grow with you.</h2><p>This page and your daily practice guidance change as your listening history shows that you are ready for more speed, nuance, and independence.</p></article></div></section>
}

function StudioView({onLeave,recordActivity,youtubeUrl,setYoutubeUrl,videoId,setVideoId,clipStart,setClipStart,clipEnd,setClipEnd,urlError,setUrlError,loadVideo,onAttempt}:{onLeave:()=>void;recordActivity:(body:Record<string,unknown>)=>Promise<any>;youtubeUrl:string;setYoutubeUrl:(value:string)=>void;videoId:string|null;setVideoId:(value:string|null)=>void;clipStart:number;setClipStart:(value:number)=>void;clipEnd:number;setClipEnd:(value:number)=>void;urlError:string;setUrlError:(value:string)=>void;loadVideo:()=>void;onAttempt:(attempt:SpeakingAttempt)=>void}){
 const [studioStep,setStudioStep]=useState(0),[transcript,setTranscript]=useState(""),[cues,setCues]=useState<CaptionCue[]>([]),[videoDuration,setVideoDuration]=useState(0),[captionSource,setCaptionSource]=useState<"manual"|"automatic"|null>(null),[captionReason,setCaptionReason]=useState(""),[transcriptState,setTranscriptState]=useState<"idle"|"loading"|"found"|"missing">("idle"),[summary,setSummary]=useState(""),[feedback,setFeedback]=useState<ComprehensionFeedback|null>(null),[checking,setChecking]=useState(false),[studioError,setStudioError]=useState(""),[recording,setRecording]=useState(false);
 const [studioRetell,setStudioRetell]=useState(""),[studioShadow,setStudioShadow]=useState(false),[studioDecoded,setStudioDecoded]=useState(false),[studioFirst,setStudioFirst]=useState(""),[studioFinished,setStudioFinished]=useState(false),[studioXp,setStudioXp]=useState(0),[studioSaving,setStudioSaving]=useState(false);
 const studioSource=`studio:${videoId}:${Math.round(clipStart)}:${Math.round(clipEnd)}`;
 const [videoPlaying,setVideoPlaying]=useState(false);
 const studioUsage=useUsage(videoId?studioFinished?"app":studioSource:null,studioStep,videoPlaying||recording);
 const hasStudioDraft=useRef(false);
 const [videoPosition,setVideoPosition]=useState(0),[restoredTranscript,setRestoredTranscript]=useState(false);
 const resetStudioLearning=()=>{setStudioShadow(false);setStudioDecoded(false);setStudioFirst("");setStudioRetell("");setStudioFinished(false);setStudioStep(0);setSummary("");setFeedback(null)};
 const studioRecovery=useSessionDraft(videoId?"studio:"+videoId:null,{version:1,title:"Studio · "+videoId,step:studioStep,done:studioFinished,transcript,cues,videoDuration,captionSource,captionReason,transcriptState,summary,feedback,studioRetell,studioShadow,studioDecoded,studioFirst,studioXp,clipStart,clipEnd,youtubeUrl,videoPosition},draft=>{
   hasStudioDraft.current=Boolean(draft);resetStudioLearning();setVideoPlaying(false);setVideoPosition(0);setTranscript("");setCues([]);setCaptionSource(null);setCaptionReason("");setTranscriptState("idle");setRestoredTranscript(false);
   if(!draft){setClipStart(0);setClipEnd(60);return}
   setStudioStep(draft.step);setStudioFinished(draft.done);setTranscript(draft.transcript||"");setCues(Array.isArray(draft.cues)?draft.cues:[]);setVideoDuration(Number(draft.videoDuration)||0);setCaptionSource(draft.captionSource||null);setCaptionReason(draft.captionReason||"");setTranscriptState(draft.transcriptState==="found"?"found":draft.transcriptState==="missing"?"missing":"idle");setRestoredTranscript(Boolean(draft.transcript)||draft.transcriptState==="missing");setSummary(draft.summary||"");setFeedback(draft.feedback||null);setStudioRetell(draft.studioRetell||"");setStudioShadow(Boolean(draft.studioShadow));setStudioDecoded(Boolean(draft.studioDecoded));setStudioFirst(draft.studioFirst||"");setStudioXp(Number(draft.studioXp)||0);setClipStart(Number(draft.clipStart)||0);setClipEnd(Number(draft.clipEnd)||60);setVideoPosition(Number(draft.videoPosition)||0);if(draft.youtubeUrl)setYoutubeUrl(draft.youtubeUrl);
 });
 const clipTranscript=cues.length?cues.filter(cue=>cue.start<clipEnd&&cue.start+Math.max(cue.duration,.5)>clipStart).map(cue=>cue.text).filter((text,index,all)=>text!==all[index-1]).join(" ").replace(/\s+([,.!?;:])/g,"$1").trim():transcript;
 useEffect(()=>{if(!videoId||!studioRecovery.ready||restoredTranscript)return;const controller=new AbortController();setTranscriptState("loading");fetch("/api/youtube-transcript",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({videoId}),signal:controller.signal}).then(response=>response.json()).then(data=>{if(controller.signal.aborted)return;const nextDuration=Number(data.durationSeconds)||0;if(nextDuration){setVideoDuration(nextDuration);if(!hasStudioDraft.current){setClipStart(0);setClipEnd(Math.min(60,nextDuration))}}if(data.transcript){setTranscript(data.transcript);setCues(Array.isArray(data.cues)?data.cues:[]);setCaptionSource(data.source||null);setTranscriptState("found")}else{setCaptionReason(data.reason||"French captions could not be retrieved.");setTranscriptState("missing")}}).catch(()=>{if(controller.signal.aborted)return;setCaptionReason("French captions could not be retrieved.");setTranscriptState("missing")});return()=>controller.abort()},[videoId,studioRecovery.ready,restoredTranscript,setClipEnd,setClipStart]);
 const check=async()=>{if(!clipTranscript.trim()){setStudioError("Add a transcript before checking comprehension.");return}setChecking(true);setStudioError("");try{const response=await fetch("/api/comprehension",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({summary,passage:clipTranscript.slice(0,4000),level:"B1-B2"})});const data=await response.json();if(!response.ok)throw new Error(data.error);setFeedback(data);setStudioFirst(summary);await recordActivity({kind:"observation",source:studioSource,score:data.score,condition:"unknown"})}catch(error){setStudioError(error instanceof Error?error.message:"Feedback is unavailable.")}finally{setChecking(false)}};
 const finishStudio=async()=>{setStudioSaving(true);const result=await recordActivity({kind:"loop",source:studioSource,usageSessionId:studioUsage.sessionId(),summary:studioFirst,retell:studioRetell,decoded:studioDecoded,rehearsed:studioShadow});if(result){setStudioFinished(true);setStudioXp(result.awarded||0)}setStudioSaving(false)};
 const resetVideo=()=>{setVideoId(null);setVideoDuration(0);setYoutubeUrl("");setStudioStep(0);setTranscript("");setSummary("");setFeedback(null)};
 return <section className="standalone-view studio-view" aria-labelledby="studio-title">
  <p className="eyebrow">Listening studio</p><h1 id="studio-title">Bring your own French.</h1>
  <p className="intro">Use the same learning loop with interviews, recipes, travel videos, or anything you already enjoy.</p>
  {videoId&&<SessionSaveStatus recovery={studioRecovery} restart={()=>{resetStudioLearning();setVideoPosition(clipStart)}}/>}
  {videoId&&!studioRecovery.ready?<SessionRecoveryGate recovery={studioRecovery} onLeave={onLeave}/>:!videoId?<div className="studio-workbench"><div className="studio-controls"><div className="studio-number">01</div><h2>Choose a short clip</h2><div className="url-row"><span className="youtube-badge">▶</span><input type="url" value={youtubeUrl} onChange={e=>{setYoutubeUrl(e.target.value);setUrlError("")}} onKeyDown={e=>e.key==="Enter"&&loadVideo()} placeholder="https://www.youtube.com/watch?v=…" aria-label="YouTube URL"/><button onClick={loadVideo}>Build practice loop</button></div>{urlError&&<p className="url-error" role="alert">{urlError}</p>}<p className="import-help">Public videos with French captions work best. If captions cannot be retrieved, you can paste the transcript.</p><div className="studio-method">{labels.map((item,index)=><div key={item.name}><span>{index+1}</span><p><strong>{item.name}</strong>{item.sub}</p></div>)}</div></div><div className="studio-screen"><div className="studio-empty"><span>écoute</span><strong>Your clip becomes a lesson</strong><p>One source. Four deliberate passes. No passive scrolling.</p></div></div></div>:
  <div className="studio-loop"><aside><button className="change-video" onClick={resetVideo}>← Choose another video</button><p className="eyebrow">Studio session</p><ol className="steps">{labels.map((item,index)=><li key={item.name} className={index===studioStep?"current":index<studioStep?"complete":""}><span className="step-icon">{index<studioStep?"✓":index+1}</span><div><strong>{item.name}</strong><small>{item.sub}</small></div></li>)}</ol></aside>
   <div className="studio-lesson">{studioFinished&&<div className="journey-card" role="status"><h2>Studio loop complete · +{studioXp} XP</h2><p>Your practice is recorded. This passage can earn review XP after 24 hours.</p><button onClick={resetVideo}>Choose another video</button></div>}<ClipTimeline duration={videoDuration} start={clipStart} end={clipEnd} onStart={value=>{resetStudioLearning();setClipStart(value);setVideoPosition(value)}} onEnd={value=>{resetStudioLearning();setClipEnd(value);setVideoPosition(clipStart)}}/><div className="stage-label"><span>0{studioStep+1}</span> {labels[studioStep].name}</div><h2>{["What did you catch?","Close the gaps.","A little practice, your way.","Now make it yours."][studioStep]}</h2>{studioStep!==2&&<YouTubePlayer videoId={videoId} start={clipStart} end={clipEnd} onPlayback={setVideoPlaying} resumeAt={videoPosition} onPosition={setVideoPosition} onDuration={actualDuration=>{if(actualDuration>0)setVideoDuration(Math.round(actualDuration))}}/>}
   {studioStep===0&&<><div className={`caption-status ${transcriptState}`}>{transcriptState==="loading"?"Reading the video’s French captions…":transcriptState==="found"?`✓ ${captionSource==="automatic"?"Automatic":"Creator-provided"} French captions found · transcript built for ${formatTime(clipStart)}–${formatTime(clipEnd)}`:`${captionReason} Paste French text below to continue.`}</div>{transcriptState==="missing"&&<textarea className="transcript-input" value={transcript} onChange={e=>setTranscript(e.target.value)} placeholder="Paste the French transcript here…"/>}<Response label="Summarize what you understood" hint="English or French is fine" text={summary} setText={value=>{setSummary(value);setFeedback(null)}} placeholder="The speaker is explaining…"/>{feedback&&<div className="comprehension-result"><div><strong>{feedback.score}%</strong><span>first-listen comprehension</span></div><section><h3>You caught</h3><ul>{feedback.understood.map(item=><li key={item}>{item}</li>)}</ul><h3>Listen for next</h3><ul>{feedback.missed.map(item=><li key={item}>{item}</li>)}</ul><p><b>Second-listen target:</b> {feedback.listening_target}</p></section></div>}</>}
   {studioStep===1&&<div className="studio-transcript" data-phrase-source={studioSource}><p className="selection-hint">Transcript for this selected passage · highlight any French to save it.</p>{clipTranscript?<p>{clipTranscript}</p>:<><p>Paste a transcript to decode this clip and save phrases from it.</p><textarea value={transcript} onChange={e=>setTranscript(e.target.value)} placeholder="Paste the French transcript here…"/></>}</div>}
   {studioStep===2&&<Rehearse key={studioSource+clipTranscript} source={studioSource} text={clipTranscript} completed={studioShadow} onComplete={()=>setStudioShadow(true)} loadAudio={text=>loadSpeech(text)} recorder={phrase=><VoiceRecorder label="Record Studio rehearsal" recording={recording} setRecording={setRecording} onAttempt={onAttempt} referenceText={phrase}/>} onRetry={()=>recordActivity({kind:"rehearse",source:studioSource,repeated:true})}/>}
   {studioStep===1&&<label className="effort-check"><input type="checkbox" checked={studioDecoded} onChange={e=>setStudioDecoded(e.target.checked)}/>I compared the transcript with what I heard and noticed a gap or confirmed my understanding.</label>}{studioStep===3&&<Response label="Retell the clip in French" hint="Use your own words" text={studioRetell} setText={setStudioRetell} placeholder="Dans cette vidéo…" allowVoice onAttempt={attempt=>{onAttempt(attempt);setStudioRetell(attempt.transcript)}}/>}
   {studioStep===0&&<button disabled={checking||summary.trim().length<15||!clipTranscript.trim()} onClick={()=>{setStudioFirst(summary);setStudioStep(1)}}>Continue without AI assessment</button>}{studioError&&<p className="ai-error" role="alert">{studioError}</p>}<div className="bottom-actions"><button className="secondary" disabled={studioStep===0} onClick={()=>setStudioStep(value=>Math.max(0,value-1))}>← Back</button><button className="primary" disabled={studioSaving||studioFinished||checking||(studioStep===0&&summary.trim().length<15)||(studioStep===1&&(!studioDecoded||!clipTranscript.trim()))||(studioStep===2&&!studioShadow)||(studioStep===3&&studioRetell.trim().length<15)} onClick={()=>{if(studioStep===0&&!feedback){void check();return}if(studioStep===3){void finishStudio();return}setStudioStep(value=>Math.min(3,value+1))}}>{checking?"Checking…":studioStep===0&&!feedback?"Check understanding":studioStep===3?"Finish Studio loop":"Continue"} <span>→</span></button></div>
   </div>
  </div>}
 </section>
}

function ProgressView({xp,completed,savedCount,practiceDates,reviews,reviewRatings,listeningPatterns,onRate,onReview}:{xp:number;completed:string[];savedCount:number;practiceDates:string[];reviews:Record<string,string>;reviewRatings:Record<string,string>;listeningPatterns:Record<string,number>;onRate:(id:string,rating:"Again"|"Hard"|"Good"|"Easy")=>void;onReview:(id:string)=>void}){
 const due=passages.filter(p=>reviews[p.id]&&new Date(reviews[p.id])<=new Date());
 const next=passages.filter(p=>reviews[p.id]&&new Date(reviews[p.id])>new Date()).sort((a,b)=>reviews[a.id].localeCompare(reviews[b.id]));
 const patterns=Object.entries(listeningPatterns).sort((a,b)=>b[1]-a[1]);
 const topPattern=patterns[0]?.[0];
 const recommendation=topPattern==="New expression"?passages.find(p=>!completed.includes(p.id)&&p.topic==="Conversation"):topPattern==="Speech too fast"?passages.find(p=>p.id==="train"):topPattern==="Sounded different"?passages.find(p=>p.id==="pluie"):passages.find(p=>!completed.includes(p.id));
 return <section className="standalone-view progress-view" aria-labelledby="progress-title"><p className="eyebrow">Your progress</p><h1 id="progress-title">A clearer ear, one session at a time.</h1><div className="progress-cards"><article><strong>{xp}</strong><span>Total XP</span></article><article><strong>{completed.length}/{passages.length}</strong><span>Lessons completed</span></article><article><strong>{practiceDates.length}</strong><span>Practice days</span></article><article><strong>{savedCount}</strong><span>Phrases saved</span></article></div><div className="review-panel"><div><p className="eyebrow">Today’s review</p><h2>{due.length?`${due.length} ${due.length===1?"lesson is":"lessons are"} ready`:"Your queue is clear"}</h2><p>{due.length?"Try each passage without the transcript, then tell the app how available it felt.":next.length?`Next review: ${new Date(reviews[next[0].id]).toLocaleDateString()}`:"Complete a lesson to begin your review schedule."}</p></div>{due.length>0&&<div>{due.map(p=><article className="review-item" key={p.id}><button className="review-open" onClick={()=>onReview(p.id)}><span>{p.level}</span><strong>{p.title}</strong><em>Open →</em></button><ReviewRating value={reviewRatings[p.id]} onRate={rating=>onRate(p.id,rating)}/></article>)}</div>}</div><div className="earprint"><div><p className="eyebrow">Your earprint</p><h2>{topPattern?topPattern:"Patterns appear as you practice"}</h2><p>{topPattern?"This is the obstacle you’ve marked most often. The recommendation beside it targets that exact kind of listening.":"During Decode, mark what made a passage difficult. We’ll turn those answers into a useful pattern—not a generic score."}</p></div><div className="pattern-bars">{patterns.length?patterns.map(([label,count])=><div key={label}><span>{label}</span><i><b style={{width:`${Math.max(18,count/(patterns[0][1]||1)*100)}%`}}/></i><strong>{count}</strong></div>):<div className="earprint-empty">No weak spots recorded yet.</div>}</div>{recommendation&&<button className="recommendation" onClick={()=>onReview(recommendation.id)}><span>Recommended next</span><strong>{recommendation.title}</strong><small>{recommendation.level} · {recommendation.topic} →</small></button>}</div><div className="level-track"><span style={{width:`${Math.min(100,completed.length/passages.length*100)}%`}}/><div><b>B1 foundation</b><b>B2 independence</b></div></div></section>
}

function YouTubePlayer({videoId,start,end,onDuration,onPlayback,resumeAt=0,onPosition}:{videoId:string;start:number;end:number;onDuration?:(seconds:number)=>void;onPlayback?:(playing:boolean)=>void;resumeAt?:number;onPosition?:(seconds:number)=>void}){
 const resumeRef=useRef(resumeAt),positionCallback=useRef(onPosition);resumeRef.current=resumeAt;positionCallback.current=onPosition;
 const hostRef=useRef<HTMLDivElement|null>(null),durationCallback=useRef(onDuration),playbackCallback=useRef(onPlayback);durationCallback.current=onDuration;playbackCallback.current=onPlayback;
 useEffect(()=>{const host=hostRef.current;if(!host)return;let player:any,cancelled=false;const mount=document.createElement("div");host.appendChild(mount);
 const report=()=>{try{if(captureActive())player?.pauseVideo?.();playbackCallback.current?.(player?.getPlayerState?.()===1);const position=Number(player?.getCurrentTime?.());if(Number.isFinite(position))positionCallback.current?.(Math.floor(position));const seconds=Number(player?.getDuration?.());if(seconds>0)durationCallback.current?.(seconds)}catch{}};
 const connect=()=>{if(cancelled)return;if(player){report();return}const YT=(window as any).YT;if(!YT?.Player)return;player=new YT.Player(mount,{host:"https://www.youtube-nocookie.com",videoId,playerVars:{start,end,rel:0,cc_load_policy:0,origin:window.location.origin},events:{onReady:()=>{const position=Math.max(start,Math.min(end-.1,resumeRef.current));if(position>start)player.seekTo(position,true);player.pauseVideo();report()},onStateChange:report}})};
 if(!document.getElementById("youtube-iframe-api")){const script=document.createElement("script");script.id="youtube-iframe-api";script.src="https://www.youtube.com/iframe_api";document.head.appendChild(script)}
 window.addEventListener(CAPTURE_PLAYBACK_EVENT,report);connect();const timer=window.setInterval(connect,500);
 return()=>{window.removeEventListener(CAPTURE_PLAYBACK_EVENT,report);cancelled=true;playbackCallback.current?.(false);window.clearInterval(timer);try{player?.destroy()}catch{}host.replaceChildren()};
 },[videoId,start,end]);
 return <div className="youtube-player"><div ref={hostRef}/></div>
}

function Response({label,hint,text,setText,placeholder,allowVoice=false,onAttempt}:{label:string;hint:string;text:string;setText:(v:string)=>void;placeholder:string;allowVoice?:boolean;onAttempt?:(attempt:SpeakingAttempt)=>void}){const [recording,setRecording]=useState(false);return <div className="response-block"><label><strong>{label}</strong><span>{hint}</span></label><textarea value={text} onChange={e=>setText(e.target.value)} placeholder={placeholder} maxLength={500}/><div className="response-footer"><span>{text.length} / 500</span>{allowVoice&&<span className="voice-hint">or use the recorder below</span>}</div>{allowVoice&&<VoiceRecorder label="Record my retell" recording={recording} setRecording={setRecording} onAttempt={onAttempt}/>}</div>}

async function measureSpeechTiming(blob:Blob){
 const context=new AudioContext();
 try{const buffer=await context.decodeAudioData(await blob.arrayBuffer());const data=buffer.getChannelData(0),windowSize=Math.max(1,Math.floor(buffer.sampleRate*.05)),levels:number[]=[];for(let start=0;start<data.length;start+=windowSize){let sum=0,end=Math.min(data.length,start+windowSize);for(let i=start;i<end;i++)sum+=data[i]*data[i];levels.push(Math.sqrt(sum/Math.max(1,end-start)))}const peak=Math.max(...levels,.001),threshold=Math.max(.008,peak*.12);let silentRun=0,longest=0,pauses=0,silentWindows=0;for(const level of levels){if(level<threshold){silentRun++;silentWindows++}else{if(silentRun>=6)pauses++;longest=Math.max(longest,silentRun);silentRun=0}}if(silentRun>=6)pauses++;longest=Math.max(longest,silentRun);return{duration_seconds:Number(buffer.duration.toFixed(1)),pause_count:pauses,longest_pause_seconds:Number((longest*.05).toFixed(1)),speaking_ratio:Number((1-silentWindows/Math.max(1,levels.length)).toFixed(2))}}finally{void context.close()}
}

function VoiceRecorder({label,recording,setRecording,onAttempt,referenceText=""}:{label:string;recording:boolean;setRecording:(v:boolean)=>void;onAttempt?:(attempt:SpeakingAttempt)=>void;referenceText?:string}){
 const [captureMode,setCaptureMode]=useState<CaptureMode>("clean"),[testOnly,setTestOnly]=useState(false),[captureSettings,setCaptureSettings]=useState<MediaTrackSettings|null>(null),[comparisons,setComparisons]=useState<{mode:CaptureMode;url:string}[]>([]);
 const testUrls=useRef<string[]>([]),releasePlayback=useRef<(()=>void)|null>(null),takeOptions=useRef({mode:"clean" as CaptureMode,testOnly:false});
 const capture=useRef<ReturnType<typeof createAudioCapture>|null>(null),mounted=useRef(false),audioObjectUrl=useRef(""),feedbackAbort=useRef<AbortController|null>(null);const [starting,setStarting]=useState(false),[devices,setDevices]=useState<MediaDeviceInfo[]>([]),[deviceId,setDeviceId]=useState("");const [audioUrl,setAudioUrl]=useState(""),[error,setError]=useState(""),[analyzing,setAnalyzing]=useState(false),[result,setResult]=useState<{transcript:string;feedback:{cefr_estimate:string;score:number;summary:string;strengths:string[];corrections:string[];word_accuracy:string;rhythm:string;pauses:string;liaison_practice:string;replay_drill:string;next_drill:string;xp_earned:number}}|null>(null);
 useEffect(()=>{if(!recording)return;const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=""};window.addEventListener("beforeunload",warn);return()=>window.removeEventListener("beforeunload",warn)},[recording]);
 const analyze=async(blob:Blob)=>{feedbackAbort.current?.abort();const controller=new AbortController();feedbackAbort.current=controller;setAnalyzing(true);setResult(null);try{const timing=await measureSpeechTiming(blob).catch(()=>null);const form=new FormData();form.append("audio",blob,audioFilename(blob.type));form.append("level","B1-B2");form.append("task",label.toLowerCase());if(referenceText)form.append("reference",referenceText);if(timing)form.append("timing",JSON.stringify(timing));const response=await fetch("/api/feedback",{method:"POST",body:form,signal:controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.error||"AI feedback is unavailable.");if(!mounted.current||controller.signal.aborted)return;setResult(data);onAttempt?.({id:crypto.randomUUID(),createdAt:new Date().toISOString(),task:label,transcript:data.transcript,score:data.feedback.score,level:data.feedback.cefr_estimate,summary:data.feedback.summary,nextDrill:data.feedback.replay_drill})}catch(e){if(mounted.current&&!controller.signal.aborted)setError(e instanceof Error?e.message:"AI feedback is unavailable.")}finally{if(mounted.current&&!controller.signal.aborted)setAnalyzing(false)}};

 const analyzeCallback=useRef(analyze);analyzeCallback.current=analyze;
 const recordingCallback=useRef(setRecording);recordingCallback.current=setRecording;
 const refreshDevices=()=>navigator.mediaDevices?.enumerateDevices?.().then(items=>{if(mounted.current)setDevices(items.filter(d=>d.kind==="audioinput"))}).catch(()=>{});
 useEffect(()=>{mounted.current=true;capture.current=createAudioCapture({
  onState:state=>{if(state==="starting"&&!releasePlayback.current)releasePlayback.current=holdAppPlayback();if(state==="idle"){releasePlayback.current?.();releasePlayback.current=null}if(mounted.current){setStarting(state==="starting");recordingCallback.current(state==="recording")}},
  onSettings:settings=>{if(mounted.current)setCaptureSettings(settings)},
  onError:message=>{if(mounted.current){setError(message);void refreshDevices()}},
  onAudio:blob=>{if(!mounted.current)return;if(takeOptions.current.testOnly){const url=URL.createObjectURL(blob);testUrls.current.push(url);if(testUrls.current.length>2)URL.revokeObjectURL(testUrls.current.shift()!);setComparisons(items=>[...items,{mode:takeOptions.current.mode,url}].slice(-2));return}if(audioObjectUrl.current)URL.revokeObjectURL(audioObjectUrl.current);audioObjectUrl.current=URL.createObjectURL(blob);setAudioUrl(audioObjectUrl.current);void analyzeCallback.current(blob)}
 });return()=>{mounted.current=false;capture.current?.cancel();releasePlayback.current?.();releasePlayback.current=null;testUrls.current.forEach(url=>URL.revokeObjectURL(url));feedbackAbort.current?.abort();if(audioObjectUrl.current)URL.revokeObjectURL(audioObjectUrl.current);recordingCallback.current(false)}},[]);
 const toggle=()=>{if(recording){capture.current?.stop();return}if(starting||analyzing)return;setError("");setResult(null);setCaptureSettings(null);takeOptions.current={mode:captureMode,testOnly};void capture.current?.start(deviceId,captureMode).then(()=>refreshDevices())};

 return <div className="recorder"><fieldset disabled={starting||recording||analyzing} className="capture-options"><legend>Recording sound</legend><label>Capture mode <select value={captureMode} onChange={e=>setCaptureMode(e.target.value as CaptureMode)}><option value="clean">Clean capture</option><option value="browser">Browser defaults (comparison)</option></select></label><label><input type="checkbox" checked={testOnly} onChange={e=>setTestOnly(e.target.checked)}/> Test only — no AI upload</label><p>Clean capture requests no automatic gain, noise suppression or echo cancellation. App playback pauses while recording. Use headphones if other apps are playing sound.</p>{testOnly&&<p>Record the same short sentence in each mode. The last two tests stay here until you leave this step.</p>}</fieldset><button className={recording?"record active":"record"} disabled={starting||analyzing} onClick={toggle}>{starting?"Opening microphone…":recording?"■ Stop recording":`● ${testOnly?"Record sound test":label}`}</button>{starting&&<button onClick={()=>capture.current?.cancel()}>Cancel microphone request</button>}{devices.length>1&&<label>Microphone <select aria-label="Recording microphone" disabled={starting||recording||analyzing} value={deviceId} onChange={e=>setDeviceId(e.target.value)}><option value="">Browser default</option>{devices.filter(d=>d.deviceId!=="default").map((d,i)=><option key={d.deviceId} value={d.deviceId}>{d.label||`Microphone ${i+1}`}</option>)}</select></label>}{comparisons.map((take,i)=><div key={take.url}><p>Test {i+1} · {take.mode==="clean"?"Clean capture":"Browser defaults"}</p><audio controls src={take.url} aria-label={`${take.mode} test recording`}/></div>)}{captureSettings&&<p className="capture-settings">Reported processing: {(["autoGainControl","noiseSuppression","echoCancellation"] as const).map(key=>`${key}: ${captureSettings[key]===undefined?"not reported":captureSettings[key]?"on":"off"}`).join(" · ")}</p>}{recording&&<span className="record-limit">Stops automatically at 1:00</span>}{audioUrl&&<audio controls src={audioUrl} aria-label="Your recorded French"/>}{analyzing&&<div className="ai-loading">Checking words, rhythm, pauses, and liaison practice…</div>}{error&&<p className="record-error" role="alert">{error}</p>}{result&&<div className="ai-feedback"><div className="feedback-score"><strong>{result.feedback.score}</strong><span>{result.feedback.cefr_estimate} estimate</span><em>Coaching saved · XP is awarded for completed practice</em></div><div><p>{result.feedback.summary}</p><strong>What worked</strong><ul>{result.feedback.strengths.map(item=><li key={item}>{item}</li>)}</ul><strong>Your transcript</strong><blockquote>{result.transcript}</blockquote><div className="speech-coach-grid"><article><span>Words</span><p>{result.feedback.word_accuracy}</p></article><article><span>Rhythm</span><p>{result.feedback.rhythm}</p></article><article><span>Pauses</span><p>{result.feedback.pauses}</p></article><article><span>Liaison to practise</span><p>{result.feedback.liaison_practice}</p></article></div><strong>Refine next</strong><ul>{result.feedback.corrections.map(item=><li key={item}>{item}</li>)}</ul><div className="replay-drill"><span>Replay drill</span>{result.feedback.replay_drill}</div><div className="next-drill">Next drill · {result.feedback.next_drill}</div></div></div>}</div>
}
